{"source":"import sys
import csv
import json
import re
from decimal import Decimal, ROUND_HALF_UP

TWO = Decimal("0.01")


def normalize_category(raw):
    """Collapse whitespace, casefold; blank -> 'uncategorized'."""
    if raw is None:
        return "uncategorized"
    collapsed = re.sub(r"\s+", " ", raw).strip()
    folded = collapsed.casefold()
    if not folded:
        return "uncategorized"
    return folded


def fmt(value):
    """Quantize to two decimals with ROUND_HALF_UP; normalize -0.00 -> 0.00."""
    q = value.quantize(TWO, rounding=ROUND_HALF_UP)
    if q == 0:
        q = Decimal("0.00")
    return str(q)


def main():
    if len(sys.argv) < 2:
        sys.stderr.write("usage: solution.py <input.csv>\n")
        sys.exit(2)

    path = sys.argv[1]
    # Read raw bytes and decode as UTF-8 to preserve input bytes.
    with open(path, "rb") as fh:
        data = fh.read()
    text = data.decode("utf-8-sig")

    reader = csv.DictReader(text.splitlines())
    totals = {}
    grand = Decimal("0")

    for row in reader:
        status = (row.get("status") or "").strip().casefold()
        if status != "paid":
            continue

        amount_raw = (row.get("amount") or "").strip()
        try:
            amount = Decimal(amount_raw)
        except Exception:
            # Unparseable amount -> cannot include per contract.
            continue

        rounded = amount.quantize(TWO, rounding=ROUND_HALF_UP)
        category = normalize_category(row.get("category"))
        totals[category] = totals.get(category, Decimal("0")) + rounded
        grand += rounded

    categories = [
        {"category": name, "total": fmt(totals[name])}
        for name in sorted(totals)
    ]

    out = {"categories": categories, "total": fmt(grand)}
    sys.stdout.write(json.dumps(out, ensure_ascii=False))
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()"}

